"""Distance from the user's location to each service (US-06).

`with_distance` takes any services query (list, category, search or one id) and returns
(service, distance_km) pairs, nearest first. On PostgreSQL the distance is computed by
PostGIS on the indexed `services.location` column (migration 0002). On SQLite, which the
unit tests use, the same filter and ordering is done in Python with the haversine formula.
"""

from sqlalchemy import Select, func, literal_column
from sqlalchemy.orm import Session

from app.geo import GeoPoint, haversine_km
from app.models import Service

# Generated by migration 0002; not mapped on the model because SQLite can't create it.
LOCATION = literal_column("services.location")


def _origin(near: GeoPoint):
    return func.geography(func.ST_SetSRID(func.ST_MakePoint(near.lng, near.lat), 4326))


def with_distance(
    db: Session, query: Select, near: GeoPoint, max_km: float | None = None
) -> list[tuple[Service, float]]:
    """Run `query` and pair each service with its distance from `near`, nearest first.

    Services further than `max_km` are left out. Ties keep the query's name order.
    """
    if db.get_bind().dialect.name == "postgresql":
        origin = _origin(near)
        distance_km = (func.ST_Distance(LOCATION, origin) / 1000.0).label("distance_km")
        query = query.add_columns(distance_km)
        if max_km is not None:
            # ST_DWithin uses the GiST index; the distance column alone could not.
            query = query.where(func.ST_DWithin(LOCATION, origin, max_km * 1000.0))
        query = query.order_by(None).order_by(distance_km, Service.name, Service.id)
        return [(service, float(km)) for service, km in db.execute(query).all()]

    rows = [
        (service, haversine_km(near, GeoPoint(service.latitude, service.longitude)))
        for service in db.scalars(query).all()
    ]
    if max_km is not None:
        rows = [row for row in rows if row[1] <= max_km]
    return sorted(rows, key=lambda row: (row[1], row[0].name, row[0].id))
